package spool_test

import (
	"bytes"
	"encoding/binary"
	"errors"
	"io"
	"testing"

	"github.com/gitdek/onair/internal/spool"
)

// Inspect(io.Reader, opening []byte) (durationMS int, err error) consumes a
// complete piece, including its copy of opening. An error means it cannot be
// joined. Duration is independent: retain usable timing even for damaged media;
// otherwise return 4000. Sum runs in each track, convert using that track's
// timescale, take the longest duration, and round up to a positive millisecond.
// Absolute decode times and composition offsets do not lengthen a piece.
// Exercise inspection through its spool caller so this test compiles on the
// old base, which has no new inspection API yet. Missing Staging is a normal
// assertion failure inside the selected test; no source is patched or skipped.
func inspect36(t *testing.T, source io.Reader, opening []byte) (int, error) {
	t.Helper()
	r := recording36(t, opening)
	s := newStager36(t, spool.Open(r.Dir), options36{OpenPiece: func(string) (io.ReadCloser, error) {
		return io.NopCloser(source), nil
	}})
	return s.InspectPiece(1)
}

func cat36(parts ...[]byte) []byte { return bytes.Join(parts, nil) }
func u36(n uint32) []byte          { return binary.BigEndian.AppendUint32(nil, n) }
func q36(n uint64) []byte          { return binary.BigEndian.AppendUint64(nil, n) }
func box36(kind string, parts ...[]byte) []byte {
	body := cat36(parts...)
	return cat36(u36(uint32(len(body)+8)), []byte(kind), body)
}
func full36(version byte, flags uint32, parts ...[]byte) []byte {
	return cat36([]byte{version, byte(flags >> 16), byte(flags >> 8), byte(flags)}, cat36(parts...))
}
func movie36(scale, dur, size uint32, version byte) []byte {
	times, duration := cat36(u36(0), u36(0)), u36(0)
	if version == 1 {
		times, duration = cat36(q36(0), q36(0)), q36(0)
	}
	tkhd := box36("tkhd", full36(version, 3, times, u36(1), u36(0), duration, make([]byte, 60)))
	mdhd := box36("mdhd", full36(version, 0, times, u36(scale), duration, u36(0)))
	hdlr := box36("hdlr", full36(0, 0, u36(0), []byte("vide"), make([]byte, 12), []byte("fixture\x00")))
	track := box36("trak", tkhd, box36("mdia", mdhd, hdlr, box36("minf")))
	trex := box36("trex", full36(0, 0, u36(1), u36(1), u36(dur), u36(size), u36(0)))
	return cat36(box36("ftyp", []byte("iso6"), u36(0), []byte("iso6mp41")),
		box36("moov", box36("mvhd", full36(0, 0, make([]byte, 8), u36(1000), make([]byte, 80))), track, box36("mvex", trex)))
}

type run36 struct {
	count      uint32
	durations  []uint32
	sizes      []uint32
	continuing bool // no data_offset: follows the preceding run
	optional   bool // first-sample flags and composition offsets
}
type fragment36 struct {
	scale, trexDur, trexSize uint32
	defaults                 bool
	duration, size           uint32
	decode                   uint64
	version                  byte
	runs                     []run36
	payload                  []byte
	large, toEnd, explicit   bool
}

func fixture36(c fragment36) (opening, piece []byte) {
	opening = movie36(c.scale, c.trexDur, c.trexSize, c.version)
	headerLen := 8
	if c.large {
		headerLen = 16
	}
	makeMoof := func(length int) []byte {
		flags := uint32(0x020002) // default-base-is-moof, sample-description-index
		fields := u36(1)
		if c.explicit {
			flags = 3 // explicit 64-bit base, two bytes past the media start
			fields = cat36(fields, q36(uint64(len(opening)+length+headerLen+2)))
		}
		fields = cat36(fields, u36(1))
		if c.defaults {
			flags |= 0x38
			fields = cat36(fields, u36(c.duration), u36(c.size), u36(0))
		}
		tfdt := full36(0, 0, u36(uint32(c.decode)))
		if c.version == 1 {
			tfdt = full36(1, 0, q36(c.decode))
		}
		parts := [][]byte{box36("tfhd", full36(0, flags, fields)), box36("tfdt", tfdt)}
		used := uint32(0)
		for _, run := range c.runs {
			flags := uint32(0)
			fields := u36(run.count)
			if !run.continuing {
				flags |= 1
				offset := int32(length+headerLen) + int32(used)
				if c.explicit {
					offset = int32(used) - 2
				}
				fields = cat36(fields, u36(uint32(offset)))
			}
			if run.optional {
				// A run cannot carry first-sample-flags and per-sample flags
				// together. Exercise first-sample-flags plus composition offsets.
				flags |= 4 | 0x800
				fields = cat36(fields, u36(0))
			}
			if run.durations != nil {
				flags |= 0x100
			}
			if run.sizes != nil {
				flags |= 0x200
			}
			for i := uint32(0); i < run.count; i++ {
				if run.durations != nil {
					fields = cat36(fields, u36(run.durations[i]))
				}
				size := c.trexSize
				if c.defaults {
					size = c.size
				}
				if run.sizes != nil {
					size = run.sizes[i]
					fields = cat36(fields, u36(size))
				}
				used += size
				if run.optional {
					fields = cat36(fields, u36(0xffffffff)) // version 1: -1
				}
			}
			parts = append(parts, box36("trun", full36(1, flags, fields)))
		}
		return box36("moof", box36("mfhd", full36(0, 0, u36(1))), box36("traf", parts...))
	}
	moof := makeMoof(0)
	moof = makeMoof(len(moof))
	mdat := box36("mdat", c.payload)
	if c.large {
		mdat = cat36(u36(1), []byte("mdat"), q36(uint64(16+len(c.payload))), c.payload)
	} else if c.toEnd {
		mdat = cat36(u36(0), []byte("mdat"), c.payload)
	}
	return opening, cat36(opening, moof, mdat)
}

func TestInspectPieceDurationsAndDefaults(t *testing.T) {
	for _, c := range []struct {
		name string
		f    fragment36
		want int
	}{
		{"sample fields override both defaults", fragment36{scale: 600, trexDur: 300, trexSize: 9, defaults: true, duration: 200, size: 8, decode: 9000000000, version: 1, runs: []run36{{count: 2, durations: []uint32{40, 20}, sizes: []uint32{2, 3}, optional: true}}, payload: []byte("abcde")}, 100},
		{"track defaults and all runs", fragment36{scale: 48000, defaults: true, duration: 1024, size: 2, runs: []run36{{count: 2}, {count: 1, continuing: true}}, payload: []byte("abcdef")}, 64},
		{"movie defaults", fragment36{scale: 1000, trexDur: 250, trexSize: 2, runs: []run36{{count: 2}}, payload: []byte("abcd")}, 500},
		{"large media and signed offset from explicit base", fragment36{scale: 600, trexDur: 40, trexSize: 1, explicit: true, large: true, runs: []run36{{count: 1}}, payload: []byte("a")}, 67},
		{"media to end and less than a millisecond", fragment36{scale: 48000, trexDur: 1, trexSize: 1, toEnd: true, runs: []run36{{count: 1}}, payload: []byte("a")}, 1},
		{"no usable duration is still readable", fragment36{scale: 1000, trexSize: 2, runs: []run36{{count: 1}}, payload: []byte("ab")}, 4000},
	} {
		opening, piece := fixture36(c.f)
		got, err := inspect36(t, bytes.NewReader(piece), opening)
		if err != nil || got != c.want {
			t.Errorf("%s: duration = %d, error = %v; want %d, nil", c.name, got, err, c.want)
		}
	}
	// Length belongs to this piece, not to all time since tfdt's origin.
	opening, piece := fixture36(fragment36{scale: 1000, trexDur: 125, trexSize: 1, runs: []run36{{count: 1}}, payload: []byte("a")})
	_, later := fixture36(fragment36{scale: 1000, trexDur: 125, trexSize: 1, decode: 125, runs: []run36{{count: 1}}, payload: []byte("b")})
	got, err := inspect36(t, bytes.NewReader(cat36(piece, later[len(opening):])), opening)
	if err != nil || got != 250 {
		t.Fatalf("two fragments: duration %d, %v; want 250", got, err)
	}
}

func TestInspectWholeFragmentAndMediaBounds(t *testing.T) {
	opening, good := fixture36(fragment36{scale: 1000, trexDur: 125, trexSize: 2, runs: []run36{{count: 2}}, payload: []byte("abcd")})
	mutate := func(at int, v uint32) []byte {
		b := bytes.Clone(good)
		binary.BigEndian.PutUint32(b[at:], v)
		return b
	}
	trun := bytes.Index(good, []byte("trun"))
	mdat := bytes.Index(good, []byte("mdat"))
	moof := bytes.Index(good, []byte("moof"))
	short := bytes.Clone(good[:len(good)-1])
	binary.BigEndian.PutUint32(short[mdat-4:], 11) // boxes fit, sample data does not
	foreign := bytes.Clone(good)
	foreign[8] ^= 1 // still a valid ftyp, but not this recording's opening
	_, shortDefault := fixture36(fragment36{scale: 1000, defaults: true, duration: 125, size: 3, runs: []run36{{count: 2}}, payload: []byte("abcde")})
	_, shortExplicit := fixture36(fragment36{scale: 1000, runs: []run36{{count: 2, durations: []uint32{125, 125}, sizes: []uint32{2, 4}}}, payload: []byte("abcde")})
	for name, bad := range map[string][]byte{
		"foreign opening":                   foreign,
		"truncated opening":                 good[:len(opening)-1],
		"no fragment":                       opening,
		"truncated media box":               good[:len(good)-1],
		"trailing partial header":           cat36(good, []byte{0, 0, 0}),
		"later malformed fragment":          cat36(good, u36(7), []byte("moof")),
		"nested box smaller than header":    mutate(trun-4, 7),
		"run count exceeds available media": mutate(trun+8, 0xffffffff),
		"offset into opening":               mutate(trun+12, uint32(-int32(moof-4))),
		"offset into mdat header":           mutate(trun+12, uint32(mdat-4-(moof-4))),
		"offset past end":                   mutate(trun+12, 0x7fffffff),
		"negative offset before file":       mutate(trun+12, 0x80000000),
		"short trex-sized data":             short,
		"short tfhd-sized data":             shortDefault,
		"short trun-sized data":             shortExplicit,
		"sample spills into non-media box":  cat36(short, box36("free", []byte("room that is not sample data"))),
		"cut large-size header after media": cat36(good, u36(1), []byte("free"), u36(0)),
		"overflowing large-size box":        cat36(good, u36(1), []byte("free"), q36(^uint64(0))),
	} {
		duration, err := inspect36(t, bytes.NewReader(bad), opening)
		if err == nil || duration <= 0 {
			t.Errorf("%s: duration %d, error %v; want positive duration and unreadable", name, duration, err)
		}
	}
	if got, err := inspect36(t, bytes.NewReader(short), opening); got != 250 || err == nil {
		t.Fatalf("media damage erased usable timing: %d, %v", got, err)
	}
	if got, err := inspect36(t, bytes.NewReader([]byte("not mp4")), opening); got != 4000 || err == nil {
		t.Fatalf("unusable metadata: %d, %v; want fallback and error", got, err)
	}
}

type reader36 struct {
	data     []byte
	read     int
	finished bool
	fault    error
}

func (r *reader36) Read(p []byte) (int, error) {
	if r.read == len(r.data) {
		r.finished = true
		if r.fault != nil {
			return 0, r.fault
		}
		return 0, io.EOF
	}
	if len(p) > 7 {
		p = p[:7]
	}
	n := copy(p, r.data[r.read:])
	r.read += n
	return n, nil
}

func TestInspectReadsThroughMediaAndReportsReadErrors(t *testing.T) {
	opening, piece := fixture36(fragment36{scale: 1000, trexDur: 125, trexSize: 4096, runs: []run36{{count: 1}}, payload: bytes.Repeat([]byte("x"), 4096)})
	piece = cat36(piece, box36("free", bytes.Repeat([]byte("z"), 300)))
	r := &reader36{data: piece}
	if duration, err := inspect36(t, r, opening); err != nil || duration != 125 || r.read != len(piece) || !r.finished {
		t.Fatalf("not a complete read: duration %d, err %v, bytes %d/%d, end %v", duration, err, r.read, len(piece), r.finished)
	}
	fault := errors.New("injected media read failure")
	for _, length := range []int{len(piece) - 500, len(piece) - 100, len(piece)} {
		r := &reader36{data: piece[:length], fault: fault}
		if duration, err := inspect36(t, r, opening); !errors.Is(err, fault) || duration != 125 || !r.finished {
			t.Errorf("read failure at %d: duration %d, error %v, end %v", length, duration, err, r.finished)
		}
	}
}

