package spool_test

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/gitdek/onair/internal/spool"
)

// Recording.Staging(StageOptions) *Stager provides the new, caller-directed path.
// All options default to real disk I/O. OpenPiece opens a requested closed
// piece; CreateOutput exclusively creates an owned hidden output; SyncDir
// flushes a directory. SyncWriteCloser is io.WriteCloser plus Sync() error.
// These narrow I/O substitutions make late failures reproducible on Linux.
// InspectPiece(n) (durationMS int, err error) reads through OpenPiece and uses
// mp4.Inspect(io.Reader, opening []byte) (int, error); durations stay available
// independently of readability, including for join omission reports.
//
// WritePiece(n, io.Reader) writes opening + media to .piece-NNNNNN.mp4.part
// and flushes/closes it. PublishPiece(n) hard-links it to piece-NNNNNN.mp4;
// DiscardPiece(n) removes only the hidden name. Numbers must be positive;
// callers choose them, so gaps do not prevent writing a requested number.
//
// PrepareJoin(dst, []int) returns a JoinPreparation with Omitted []int and
// DurationsMS []int (one entry per requested number), and an error. It writes
// .<basename>.part beside dst, but never publishes. The inventory must be
// positive, unique and increasing; it is not derived from Pieces().
// PublishJoin(dst) and DiscardJoin(dst) separately publish or discard it.
//
// Publication retains the hidden hard link until explicit discard, letting a
// new Stager recognize the same inode after a kill. Equal bytes in a different
// file are a conflict, as are symlinks. A caller saves the publication result
// before discard and saves the omission/duration report before publication.
// Calls for a recording are serialized by that caller; this layer owns no
// lifecycle, numbering, finality, retention policy or persistent core record.
type output36 interface {
	io.WriteCloser
	Sync() error
}
type options36 struct {
	OpenPiece    func(string) (io.ReadCloser, error)
	CreateOutput func(string) (output36, error)
	SyncDir      func(string) error
}
type stagingOps36 interface {
	InspectPiece(int) (int, error)
	WritePiece(int, io.Reader) error
	PublishPiece(int) error
	DiscardPiece(int) error
	PublishJoin(string) error
	DiscardJoin(string) error
}
type preparation36 struct{ Omitted, DurationsMS []int }
type stager36 struct {
	stagingOps36
	t     *testing.T
	value reflect.Value
}

// Reflection is limited to loading the proposed API and its new named option
// and report types. All actual calls and assertions below exercise production
// behavior. This lets base go vet compile the test and the selected Test fail
// explicitly on missing API, instead of stopping before any test can run.
func newStager36(t *testing.T, r *spool.Recording, opts options36) *stager36 {
	t.Helper()
	factory := reflect.ValueOf(r).MethodByName("Staging")
	if !factory.IsValid() {
		t.Fatal("Recording.Staging is missing: core-directed disk operations are not implemented")
	}
	ft := factory.Type()
	if ft.NumIn() != 1 || ft.In(0).Kind() != reflect.Struct || ft.NumOut() != 1 {
		t.Fatal("Recording.Staging must take StageOptions and return *Stager")
	}
	option := reflect.New(ft.In(0)).Elem()
	set := func(name string, value any) {
		t.Helper()
		field := option.FieldByName(name)
		v := reflect.ValueOf(value)
		if !field.IsValid() || !field.CanSet() || !v.Type().AssignableTo(field.Type()) {
			t.Fatalf("StageOptions.%s has the wrong type", name)
		}
		field.Set(v)
	}
	if opts.OpenPiece != nil {
		set("OpenPiece", opts.OpenPiece)
	}
	if opts.SyncDir != nil {
		set("SyncDir", opts.SyncDir)
	}
	if opts.CreateOutput != nil {
		field := option.FieldByName("CreateOutput")
		if !field.IsValid() || !field.CanSet() || field.Kind() != reflect.Func {
			t.Fatal("StageOptions.CreateOutput is missing or not a function")
		}
		ct := field.Type()
		if ct.NumIn() != 1 || ct.In(0).Kind() != reflect.String || ct.NumOut() != 2 || ct.Out(0).Kind() != reflect.Interface || ct.Out(1) != reflect.TypeOf((*error)(nil)).Elem() {
			t.Fatal("StageOptions.CreateOutput must return SyncWriteCloser and error")
		}
		field.Set(reflect.MakeFunc(ct, func(args []reflect.Value) []reflect.Value {
			w, err := opts.CreateOutput(args[0].String())
			out := reflect.Zero(ct.Out(0))
			failure := reflect.Zero(ct.Out(1))
			if w != nil {
				out = reflect.ValueOf(w)
			}
			if err != nil {
				failure = reflect.ValueOf(err)
			}
			return []reflect.Value{out, failure}
		}))
	}
	value := factory.Call([]reflect.Value{option})[0]
	ops, ok := value.Interface().(stagingOps36)
	if !ok {
		t.Fatal("Stager does not provide inspection and separate write, publish and discard operations")
	}
	return &stager36{stagingOps36: ops, t: t, value: value}
}
func (s *stager36) PrepareJoin(dst string, inventory []int) (preparation36, error) {
	s.t.Helper()
	method := s.value.MethodByName("PrepareJoin")
	if !method.IsValid() {
		s.t.Fatal("Stager.PrepareJoin is missing")
	}
	mt := method.Type()
	if mt.NumIn() != 2 || mt.In(0) != reflect.TypeOf("") || mt.In(1) != reflect.TypeOf([]int{}) || mt.NumOut() != 2 || mt.Out(0).Kind() != reflect.Struct || mt.Out(1) != reflect.TypeOf((*error)(nil)).Elem() {
		s.t.Fatal("PrepareJoin must take (string, []int) and return (JoinPreparation, error)")
	}
	result := method.Call([]reflect.Value{reflect.ValueOf(dst), reflect.ValueOf(inventory)})
	var report preparation36
	for name, dest := range map[string]*[]int{"Omitted": &report.Omitted, "DurationsMS": &report.DurationsMS} {
		field := result[0].FieldByName(name)
		if !field.IsValid() || !field.CanInterface() {
			s.t.Fatalf("JoinPreparation.%s is missing", name)
		}
		value, ok := field.Interface().([]int)
		if !ok {
			s.t.Fatalf("JoinPreparation.%s must be []int", name)
		}
		*dest = value
	}
	var err error
	if !result[1].IsNil() {
		err = result[1].Interface().(error)
	}
	return report, err
}

func concat36(parts ...[]byte) []byte { return bytes.Join(parts, nil) }
func word36(n uint32) []byte          { return binary.BigEndian.AppendUint32(nil, n) }
func atom36(kind string, parts ...[]byte) []byte {
	body := concat36(parts...)
	return concat36(word36(uint32(8+len(body))), []byte(kind), body)
}
func fields36(flags uint32, parts ...[]byte) []byte {
	return concat36(word36(flags), concat36(parts...))
}

// These boxes have one 1000 Hz track and one sample per fragment. Timing and
// size are tfhd defaults and trun addresses the mdat relative to the moof.
// Opening is identical for every piece, including those of different lengths.
func sample36(decode, duration uint32, payload string) (opening, piece []byte) {
	tkhd := atom36("tkhd", fields36(3, make([]byte, 8), word36(1), word36(0), word36(0), make([]byte, 60)))
	mdhd := atom36("mdhd", fields36(0, make([]byte, 8), word36(1000), word36(0), word36(0)))
	hdlr := atom36("hdlr", fields36(0, word36(0), []byte("vide"), make([]byte, 12), []byte("fixture\x00")))
	track := atom36("trak", tkhd, atom36("mdia", mdhd, hdlr, atom36("minf")))
	trex := atom36("trex", fields36(0, word36(1), word36(1), word36(0), word36(0), word36(0)))
	opening = concat36(atom36("ftyp", []byte("iso6"), word36(0), []byte("iso6mp41")),
		atom36("moov", atom36("mvhd", fields36(0, make([]byte, 8), word36(1000), make([]byte, 80))), track, atom36("mvex", trex)))
	makeMoof := func(offset uint32) []byte {
		tfhd := atom36("tfhd", fields36(0x020018, word36(1), word36(duration), word36(uint32(len(payload)))))
		tfdt := atom36("tfdt", fields36(0x01000000, binary.BigEndian.AppendUint64(nil, uint64(decode))))
		trun := atom36("trun", fields36(1, word36(1), word36(offset)))
		return atom36("moof", atom36("mfhd", fields36(0, word36(1))), atom36("traf", tfhd, tfdt, trun))
	}
	moof := makeMoof(0)
	moof = makeMoof(uint32(len(moof) + 8))
	return opening, concat36(opening, moof, atom36("mdat", []byte(payload)))
}

func recording36(t *testing.T, opening []byte) *spool.Recording {
	t.Helper()
	r, err := spool.Create(t.TempDir(), "recording")
	if err != nil {
		t.Fatal(err)
	}
	if err := r.PutOpening(opening); err != nil {
		t.Fatal(err)
	}
	return r
}
func name36(r *spool.Recording, n int) string {
	return filepath.Join(r.Dir, fmt.Sprintf("piece-%06d.mp4", n))
}
func hidden36(path string) string {
	return filepath.Join(filepath.Dir(path), "."+filepath.Base(path)+".part")
}
func write36(t *testing.T, path string, data []byte) {
	t.Helper()
	if err := os.WriteFile(path, data, 0o600); err != nil {
		t.Fatal(err)
	}
}
func read36(t *testing.T, path string) []byte {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return b
}
func absent36(t *testing.T, path string) {
	t.Helper()
	if _, err := os.Lstat(path); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("%s should not exist: %v", path, err)
	}
}
func same36(t *testing.T, a, b string) {
	t.Helper()
	x, err := os.Lstat(a)
	if err != nil {
		t.Fatal(err)
	}
	y, err := os.Lstat(b)
	if err != nil {
		t.Fatal(err)
	}
	if !x.Mode().IsRegular() || !y.Mode().IsRegular() || !os.SameFile(x, y) {
		t.Fatalf("%s and %s are not the same regular file", a, b)
	}
}

func TestPieceWritingPublicationAndDiscardAreSeparate(t *testing.T) {
	opening, piece := sample36(12000, 250, "short final media")
	r := recording36(t, opening)
	s := newStager36(t, r, options36{})
	named := name36(r, 7)
	if err := s.WritePiece(7, bytes.NewReader(piece[len(opening):])); err != nil {
		t.Fatal(err)
	}
	absent36(t, named)
	if !bytes.Equal(read36(t, hidden36(named)), piece) {
		t.Fatal("staged piece is not opening plus media")
	}
	if err := s.PublishPiece(7); err != nil {
		t.Fatal(err)
	}
	same36(t, named, hidden36(named))
	s = newStager36(t, spool.Open(r.Dir), options36{}) // process lost its memory
	if err := s.PublishPiece(7); err != nil {
		t.Fatalf("completed publication was not recognized: %v", err)
	}
	for i := 0; i < 2; i++ {
		if err := s.DiscardPiece(7); err != nil {
			t.Fatal(err)
		}
	}
	absent36(t, hidden36(named))
	if !bytes.Equal(read36(t, named), piece) {
		t.Fatal("discard changed the published piece")
	}
	if err := s.WritePiece(7, bytes.NewReader([]byte("replacement"))); err == nil {
		t.Fatal("a named piece was writable again")
	}
	if !bytes.Equal(read36(t, named), piece) {
		t.Fatal("repeated write changed named bytes")
	}
	if _, done := r.Done(); done {
		t.Fatal("staging decided capture finality")
	}
}

type faultReader36 struct{ err error }

func (r faultReader36) Read([]byte) (int, error) { return 0, r.err }

func TestInterruptedPieceWritesAndOccupiedNamesAreSafe(t *testing.T) {
	opening, piece := sample36(0, 1000, "complete media")
	r := recording36(t, opening)
	s := newStager36(t, r, options36{})
	fault := errors.New("capture stream was interrupted")
	source := io.MultiReader(bytes.NewReader(piece[len(opening):len(piece)-2]), faultReader36{fault})
	if err := s.WritePiece(3, source); err == nil {
		t.Fatal("interrupted source counted as a flushed piece")
	}
	absent36(t, name36(r, 3))
	if err := s.DiscardPiece(3); err != nil {
		t.Fatal(err)
	}
	absent36(t, hidden36(name36(r, 3)))
	if err := s.WritePiece(3, bytes.NewReader(piece[len(opening):])); err != nil {
		t.Fatal(err)
	}
	// A crash may leave a partial hidden file. Reuse requires explicit discard;
	// writing must never truncate a leftover file, including a hard link.
	stale := hidden36(name36(r, 4))
	write36(t, stale, []byte("interrupted attempt"))
	if err := s.WritePiece(4, bytes.NewReader([]byte("new"))); err == nil || string(read36(t, stale)) != "interrupted attempt" {
		t.Fatalf("hidden remnant was overwritten: %v", err)
	}
	if err := s.DiscardPiece(4); err != nil {
		t.Fatal(err)
	}
	write36(t, name36(r, 5), []byte("conflicting named piece"))
	if err := s.WritePiece(5, bytes.NewReader([]byte("new"))); err == nil || string(read36(t, name36(r, 5))) != "conflicting named piece" {
		t.Fatalf("named piece was overwritten: %v", err)
	}
	outside := filepath.Join(t.TempDir(), "keep")
	write36(t, outside, []byte("untouched"))
	for _, n := range []int{6, 8} {
		path := hidden36(name36(r, n))
		if n == 8 {
			path = name36(r, n)
		}
		if err := os.Symlink(outside, path); err != nil {
			t.Fatal(err)
		}
		if err := s.WritePiece(n, bytes.NewReader([]byte("new"))); err == nil {
			t.Fatalf("wrote through occupied name %s", path)
		}
	}
	if string(read36(t, outside)) != "untouched" {
		t.Fatal("writing followed a symlink")
	}
	for _, n := range []int{0, -1} {
		if err := s.WritePiece(n, bytes.NewReader([]byte("new"))); err == nil {
			t.Fatalf("accepted invalid piece number %d", n)
		}
	}
	// Even a byte-identical separate file is not evidence that our link ran.
	write36(t, name36(r, 3), piece)
	if err := s.PublishPiece(3); err == nil {
		t.Fatal("a different inode counted as this publication")
	}
	if !bytes.Equal(read36(t, name36(r, 3)), piece) || !bytes.Equal(read36(t, hidden36(name36(r, 3))), piece) {
		t.Fatal("conflicting publication changed either file")
	}
}

func TestJoinPreparationOmitsBadPiecesAndKeepsTimelineGaps(t *testing.T) {
	opening, first := sample36(0, 1000, "first")
	_, damaged := sample36(1000, 750, "second")
	// Keep every box length truthful but remove one byte of declared media.
	damaged = bytes.Clone(damaged[:len(damaged)-1])
	mdat := bytes.Index(damaged, []byte("mdat"))
	binary.BigEndian.PutUint32(damaged[mdat-4:], uint32(len(damaged)-(mdat-4)))
	_, foreign := sample36(1750, 1000, "foreign")
	foreign[8] ^= 1
	_, last := sample36(9000, 250, "later")
	r := recording36(t, opening)
	originals := map[int][]byte{1: first, 2: damaged, 3: foreign, 6: []byte("unrequested"), 7: last}
	for n, b := range originals {
		write36(t, name36(r, n), b)
	}
	if err := os.Mkdir(name36(r, 5), 0o700); err != nil {
		t.Fatal(err)
	}
	write36(t, filepath.Join(name36(r, 5), "keep"), []byte("directory contents"))
	dst := filepath.Join(r.Dir, "joined.mp4")
	s := newStager36(t, r, options36{})
	report, err := s.PrepareJoin(dst, []int{1, 2, 3, 5, 7, 8})
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(report.Omitted, []int{2, 3, 5, 8}) || len(report.DurationsMS) != 6 {
		t.Fatalf("wrong join report: %+v", report)
	}
	for _, d := range report.DurationsMS {
		if d <= 0 {
			t.Fatalf("nonpositive duration: %+v", report)
		}
	}
	if report.DurationsMS[0] != 1000 || report.DurationsMS[1] != 750 || report.DurationsMS[3] != 4000 || report.DurationsMS[4] != 250 || report.DurationsMS[5] != 4000 {
		t.Fatalf("duration and readability were conflated: %+v", report)
	}
	want := concat36(first, last[len(opening):])
	absent36(t, dst)
	if got := read36(t, hidden36(dst)); !bytes.Equal(got, want) {
		t.Fatal("join did not keep the exact ordered fragments, their 9-second decode time, and the opening once")
	}
	if _, done := r.Done(); done {
		t.Fatal("preparation marked recording done")
	}
	if err := s.PublishJoin(dst); err != nil {
		t.Fatal(err)
	}
	same36(t, dst, hidden36(dst))
	if err := s.DiscardJoin(dst); err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(read36(t, dst), want) {
		t.Fatal("publication changed prepared bytes")
	}
	for n, b := range originals {
		if !bytes.Equal(read36(t, name36(r, n)), b) {
			t.Fatalf("piece %d changed", n)
		}
	}
	if string(read36(t, filepath.Join(name36(r, 5), "keep"))) != "directory contents" {
		t.Fatal("unreadable piece was removed")
	}
}

type observed36 struct {
	f          *os.File
	bytes      int
	ended      bool
	closed     int
	errorAtEnd error
}

func (r *observed36) Read(p []byte) (int, error) {
	if len(p) > 5 {
		p = p[:5]
	}
	n, err := r.f.Read(p)
	r.bytes += n
	if err == io.EOF {
		r.ended = true
		if r.errorAtEnd != nil {
			err = r.errorAtEnd
		}
	}
	return n, err
}
func (r *observed36) Close() error { r.closed++; return r.f.Close() }

func TestJoinReadsEveryRequestedPieceOnceThroughItsEnd(t *testing.T) {
	opening, first := sample36(0, 1000, "first")
	_, middle := sample36(1000, 1000, "whole bytes followed by a read failure")
	_, last := sample36(3000, 250, "last")
	r := recording36(t, opening)
	originals := map[int][]byte{1: first, 2: middle, 4: last}
	for n, b := range originals {
		write36(t, name36(r, n), b)
	}
	var opened []string
	seen := map[string]*observed36{}
	opts := options36{OpenPiece: func(path string) (io.ReadCloser, error) {
		opened = append(opened, path)
		if _, twice := seen[path]; twice {
			return nil, errors.New("piece opened twice")
		}
		f, err := os.Open(path)
		if err != nil {
			return nil, err
		}
		reader := &observed36{f: f}
		if path == name36(r, 2) {
			reader.errorAtEnd = errors.New("read failed after all media bytes")
		}
		seen[path] = reader
		return reader, nil
	}}
	dst := filepath.Join(r.Dir, "once.mp4")
	report, err := newStager36(t, r, opts).PrepareJoin(dst, []int{1, 2, 3, 4})
	if err != nil || !reflect.DeepEqual(report.Omitted, []int{2, 3}) || !reflect.DeepEqual(report.DurationsMS, []int{1000, 1000, 4000, 250}) {
		t.Fatalf("read errors: %+v, %v", report, err)
	}
	if !reflect.DeepEqual(opened, []string{name36(r, 1), name36(r, 2), name36(r, 3), name36(r, 4)}) {
		t.Fatalf("not one ordered open per requested piece: %v", opened)
	}
	for n, b := range originals {
		reader := seen[name36(r, n)]
		if reader == nil || reader.bytes != len(b) || !reader.ended || reader.closed != 1 {
			t.Fatalf("piece %d was not read fully and closed exactly once: %+v", n, reader)
		}
	}
	if !bytes.Equal(read36(t, hidden36(dst)), concat36(first, last[len(opening):])) {
		t.Fatal("a failed read contributed bytes or prevented a later piece")
	}
	absent36(t, dst)
}

