type failingOutput36 struct {
	f      *os.File
	mode   string
	left   int
	events *[]string
}

func (w *failingOutput36) Write(p []byte) (int, error) {
	if w.events != nil {
		*w.events = append(*w.events, "write")
	}
	if w.mode == "write" && len(p) > w.left {
		n, err := w.f.Write(p[:w.left])
		w.left = 0
		if err != nil {
			return n, err
		}
		return n, errors.New("output disk is full")
	}
	n, err := w.f.Write(p)
	w.left -= n
	return n, err
}
func (w *failingOutput36) Sync() error {
	if w.events != nil {
		*w.events = append(*w.events, "sync")
	}
	if w.mode == "sync" {
		return errors.New("output flush failed")
	}
	return w.f.Sync()
}
func (w *failingOutput36) Close() error {
	if w.events != nil {
		*w.events = append(*w.events, "close")
	}
	err := w.f.Close()
	if w.mode == "close" && err == nil {
		return errors.New("output close failed")
	}
	return err
}

