func TestStagingFlushesFilesAndDirectoryChanges(t *testing.T) {
	opening, piece := sample36(0, 1000, "whole")
	r := recording36(t, opening)
	var events []string
	directoryFlushes := 0
	failDirectory := false
	opts := options36{
		CreateOutput: func(path string) (output36, error) {
			f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
			if err != nil {
				return nil, err
			}
			return &failingOutput36{f: f, events: &events}, nil
		},
		SyncDir: func(path string) error {
			directoryFlushes++
			if path != r.Dir {
				t.Errorf("flushed %s, want %s", path, r.Dir)
			}
			if failDirectory {
				return errors.New("directory flush failed")
			}
			d, err := os.Open(path)
			if err != nil {
				return err
			}
			defer d.Close()
			return d.Sync()
		},
	}
	s := newStager36(t, r, opts)
	flushedOutput := func() {
		t.Helper()
		if len(events) < 3 || events[len(events)-2] != "sync" || events[len(events)-1] != "close" {
			t.Fatalf("completed output was not flushed then closed: %v", events)
		}
		events = nil
	}
	flushedDirectory := func(op func() error) {
		t.Helper()
		before := directoryFlushes
		if err := op(); err != nil || directoryFlushes <= before {
			t.Fatalf("directory mutation was not flushed: %v, calls %d to %d", err, before, directoryFlushes)
		}
	}
	if err := s.WritePiece(1, bytes.NewReader(piece[len(opening):])); err != nil {
		t.Fatal(err)
	}
	flushedOutput()
	failDirectory = true
	if err := s.PublishPiece(1); err == nil {
		t.Fatal("publication hid a directory flush failure")
	}
	same36(t, name36(r, 1), hidden36(name36(r, 1)))
	failDirectory = false
	flushedDirectory(func() error { return s.PublishPiece(1) })
	failDirectory = true
	if err := s.DiscardPiece(1); err == nil {
		t.Fatal("discard hid a directory flush failure")
	}
	failDirectory = false
	flushedDirectory(func() error { return s.DiscardPiece(1) })
	dst := filepath.Join(r.Dir, "joined.mp4")
	if _, err := s.PrepareJoin(dst, []int{1}); err != nil {
		t.Fatal(err)
	}
	flushedOutput()
	flushedDirectory(func() error { return s.PublishJoin(dst) })
	flushedDirectory(func() error { return s.PublishJoin(dst) })
	flushedDirectory(func() error { return s.DiscardJoin(dst) })
	flushedDirectory(func() error { return s.DiscardJoin(dst) })
	if !bytes.Equal(read36(t, dst), piece) || !bytes.Equal(read36(t, name36(r, 1)), piece) {
		t.Fatal("directory retry changed media")
	}
}

